-- Phase 2 identity: institutions, users, refresh sessions.
-- UUIDs are generated by the application (UUID v7).

CREATE TABLE institutions (
    id          uuid PRIMARY KEY,
    name        text NOT NULL,
    slug        text NOT NULL,
    domain      text,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT institutions_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT institutions_slug_not_blank CHECK (btrim(slug) <> '')
);

CREATE UNIQUE INDEX institutions_slug_key ON institutions (slug);
CREATE UNIQUE INDEX institutions_name_lower_key ON institutions (lower(name));
CREATE UNIQUE INDEX institutions_domain_lower_key
    ON institutions (lower(domain))
    WHERE domain IS NOT NULL;

CREATE TABLE users (
    id                    uuid PRIMARY KEY,
    name                  text NOT NULL,
    email                 citext NOT NULL,
    password_hash         text NOT NULL,
    password_algorithm    text NOT NULL,
    institution_id        uuid NOT NULL REFERENCES institutions (id) ON DELETE RESTRICT,
    major                 text NOT NULL,
    year                  text NOT NULL,
    learning_style        text NOT NULL DEFAULT '',
    performance_level     smallint NOT NULL DEFAULT 3,
    profile_picture_key   text,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now(),
    deleted_at            timestamptz,
    CONSTRAINT users_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT users_major_not_blank CHECK (btrim(major) <> ''),
    CONSTRAINT users_year_valid CHECK (
        year IN ('Freshman', 'Sophomore', 'Junior', 'Senior', 'Graduate')
    ),
    CONSTRAINT users_password_algorithm_valid CHECK (
        password_algorithm IN ('argon2id', 'bcrypt')
    ),
    CONSTRAINT users_performance_level_valid CHECK (
        performance_level BETWEEN 1 AND 5
    ),
    CONSTRAINT users_profile_picture_key_not_url CHECK (
        profile_picture_key IS NULL
        OR (
            position('://' in profile_picture_key) = 0
            AND position('..' in profile_picture_key) = 0
        )
    )
);

CREATE UNIQUE INDEX users_email_key ON users (email);
CREATE INDEX users_institution_id_idx ON users (institution_id);

CREATE TABLE refresh_sessions (
    id          uuid PRIMARY KEY,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash  text NOT NULL,
    expires_at  timestamptz NOT NULL,
    revoked_at  timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX refresh_sessions_token_hash_key ON refresh_sessions (token_hash);
CREATE INDEX refresh_sessions_user_id_idx ON refresh_sessions (user_id);
CREATE INDEX refresh_sessions_active_idx
    ON refresh_sessions (token_hash)
    WHERE revoked_at IS NULL;
